import { Router } from 'express';
import { loginController, registerController, refreshTokenController, verifyEmailController, changePasswordController, requestVerificationCodeController, validateResetTokenController, requestPasswordResetController, passwordResetController, logoutController, softDeleteUserController, registerAdminController, registerStaffController, loginAdminController, restoreUserController, } from '../controllers/auth.controller';
import { authMiddleware, requireAdmin } from '../middlewares/auth.middleware';
const router = Router();
router.post('/login', loginController);
router.post('/register', registerController);
router.post('/refresh-token', refreshTokenController);
router.post('/verify-email', verifyEmailController);
router.post('/change-password', authMiddleware, changePasswordController);
router.post('/request-verification-code', requestVerificationCodeController);
router.post('/validate-reset-token', validateResetTokenController);
router.post('/request-password-reset', requestPasswordResetController);
router.post('/reset-password', passwordResetController);
router.post('/logout', authMiddleware, logoutController);
router.delete('/:id', authMiddleware, softDeleteUserController);
router.post('/admin/login', loginAdminController);
router.post('/admin/register', authMiddleware, requireAdmin, registerAdminController);
router.post('/admin/staff/register', authMiddleware, requireAdmin, registerStaffController);
router.patch('/admin/:id/restore', authMiddleware, requireAdmin, restoreUserController);
export default router;
